def parse_amount(s):
    if not isinstance(s, str):
        return None

    text = s
    if text.startswith(("+", "-")):
        text = text[1:]

    if not text:
        return None

    parts = text.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    if not whole.isdigit():
        return None

    if len(parts) == 2:
        fraction = parts[1]
        if not fraction or len(fraction) > 2 or not fraction.isdigit():
            return None

    try:
        amount = Decimal(s) * 100
        return int(amount)
    except (InvalidOperation, ValueError, OverflowError):
        return None


