                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue

                payment_amount = payment.get("amount")
                if (
                    not isinstance(payment_amount, int)
                    or isinstance(payment_amount, bool)
                    or payment_amount < 0
                ):
                    continue

                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue
                if payment_time < order_time or payment_time > latest_time:
                    continue

                if chosen_time is None or payment_time < chosen_time:
                    chosen_payment = payment
                    chosen_time = payment_time

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
