"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    s = s.strip()
    if not s:
        return None

    if s[0] in "+-":
        digits = s[1:]
    else:
        digits = s

    if not digits:
        return None
    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if not fraction or not fraction.isdigit() or len(fraction) > 2:
            return None
        cents = int(fraction.ljust(2, "0"))
    else:
        if not digits.isdigit():
            return None
        whole = digits
        cents = 0

    amount = int(whole) * 100 + cents
    if s.startswith("-"):
        amount = -amount
    return amount


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text.strip(), "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    seen = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in seen:
            continue

        seen.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None
        chosen_index = None

        for index, payment in enumerate(records):
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue

            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if not isinstance(order_time, datetime) or not isinstance(payment_time, datetime):
                continue
            if payment_time < order_time:
                continue
            if payment_time > order_time + timedelta(hours=72):
                continue

            if (chosen is None
                    or payment_time < chosen["timestamp"]
                    or (payment_time == chosen["timestamp"] and index < chosen_index)):
                chosen = payment
                chosen_index = index

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and isinstance(record.get("amount"), int)
                and record["amount"] < 0):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

