        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or not all("0" <= character <= "9" for character in whole):
        return None
    if fraction and not all("0" <= character <= "9" for character in fraction):
        return None
    if len(fraction) > 2:
        return None

    try:
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None

    cents = int(amount * 100)
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not timestamp_text[:4].isdigit()
        or not timestamp_text[5:7].isdigit()
        or not timestamp_text[8:10].isdigit()
        or not timestamp_text[11:13].isdigit()
        or not timestamp_text[14:16].isdigit()
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        earliest_time = order["timestamp"]
        latest_time = order["timestamp"] + timedelta(hours=72)
        chosen_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if payment["timestamp"] < earliest_time:
                continue
            if payment["timestamp"] > latest_time:
                continue

            if (
                chosen_payment is None
                or payment["timestamp"] < chosen_payment["timestamp"]
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result["status"].casefold()

        if status == "matched":
            matched_count += 1
            matched_total += result["amount"]
        elif status == "unmatched":
            unmatched_ids.append(result["order_id"])

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

