"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if re.fullmatch(r"[+-]?[0-9]+(?:\.[0-9]{1,2})?", s) is None:
        return None
    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None

    kind, record_id, order_id, amount_text, timestamp_text = fields
    kind = kind.upper()
    if kind not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if kind == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if kind == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None

        if isinstance(order_time, datetime):
            latest = order_time + timedelta(hours=72)
            for payment in records:
                if (
                    isinstance(payment, dict)
                    and payment.get("type") == "PAYMENT"
                    and payment.get("order_id") == order_id
                    and isinstance(payment.get("amount"), int)
                    and payment.get("amount") >= 0
                    and isinstance(payment.get("timestamp"), datetime)
                    and order_time <= payment["timestamp"] <= latest
                ):
                    if chosen is None or payment["timestamp"] < chosen["timestamp"]:
                        chosen = payment

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") < 0
        ):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        else:
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

