"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if not s or s.count(".") > 1:
        return None

    if "." in s:
        whole, fraction = s.split(".")
        if not whole or not whole.isdigit() or not fraction.isdigit():
            return None
        if len(fraction) > 2:
            return None
        fraction = fraction.ljust(2, "0")
    else:
        whole = s
        fraction = "00"
        if not whole.isdigit():
            return None

    return sign * (int(whole) * 100 + int(fraction))


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    type_text, record_id, order_id, amount_text, timestamp_text = fields
    record_type = type_text.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError, OverflowError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    if not records:
        return results

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        chosen = None
        order_time = order.get("timestamp")
        if not isinstance(order_time, datetime):
            continue

        latest = order_time + timedelta(hours=72)

        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue

            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if not isinstance(amount, int) or isinstance(amount, bool):
                continue
            if amount < 0 or not isinstance(payment_time, datetime):
                continue
            if payment_time < order_time or payment_time > latest:
                continue

            if chosen is None or payment_time < chosen.get("timestamp"):
                chosen = payment

        if chosen is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": chosen.get("amount"),
            })

    return results


def compute_refunds(records):
    if not records:
        return 0

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += abs(amount)
    return total


def build_summary(matches, refund_total):
    total_orders = 0
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    if matches:
        for result in matches:
            if not isinstance(result, dict):
                continue

            total_orders += 1
            status = result.get("status")
            if isinstance(status, str) and status.lower() == "matched":
                matched_count += 1
                amount = result.get("amount")
                if isinstance(amount, int) and not isinstance(amount, bool):
                    net_total += amount
            elif isinstance(status, str) and status.lower() == "unmatched":
                unmatched_ids.append(result.get("order_id"))

    if isinstance(refund_total, int) and not isinstance(refund_total, bool):
        net_total -= refund_total

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

