    if number.count(".") > 1:
        return None

    if "." in number:
        whole, fraction = number.split(".")
        if not whole.isdigit() or not fraction.isdigit():
            return None
        if len(fraction) > 2:
            return None
    else:
        whole = number
        fraction = ""
        if not whole.isdigit():
            return None

    try:
        cents = int(whole) * 100
        if len(fraction) == 1:
            cents += int(fraction) * 10
        elif len(fraction) == 2:
            cents += int(fraction)
    except (TypeError, ValueError):
        return None

    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
