def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        chosen_payment = None

        for payment in records:
            if (
                not isinstance(payment, dict)
                or payment.get("type") != "PAYMENT"
                or payment.get("order_id") != order.get("order_id")
            ):
                continue

            amount = payment.get("amount")
            if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
                continue

            payment_time = payment.get("timestamp")
            order_time = order.get("timestamp")
            if not isinstance(payment_time, datetime) or not isinstance(order_time, datetime):
                continue

            if payment_time < order_time:
                continue
            if payment_time > order_time + timedelta(hours=72):
                continue

            if (
                chosen_payment is None
                or payment_time < chosen_payment.get("timestamp")
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": chosen_payment.get("amount"),
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status", "")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

