"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if s == "":
        return None

    if "." in s:
        if s.count(".") != 1:
            return None
        whole, fraction = s.split(".")
        if whole == "" or fraction == "" or len(fraction) > 2:
            return None
    else:
        whole = s
        fraction = ""

    if not whole or any(ch < "0" or ch > "9" for ch in whole):
        return None
    if any(ch < "0" or ch > "9" for ch in fraction):
        return None

    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)

    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    payments = [
        record for record in records
        if record["type"] == "PAYMENT" and record["amount"] >= 0
    ]
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        latest = order["timestamp"] + timedelta(hours=72)
        chosen = None

        for payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if order["timestamp"] <= payment["timestamp"] <= latest:
                if chosen is None or payment["timestamp"] < chosen["timestamp"]:
                    chosen = payment

        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if match["status"].lower() == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

