"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    import re
    if not isinstance(s, str):
        return None
    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None
    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    import re
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text) is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    payments = {}
    for index, record in enumerate(records):
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") >= 0
        ):
            payments.setdefault(record.get("order_id"), []).append((index, record))

    results = []
    for record in records:
        if not isinstance(record, dict) or record.get("type") != "ORDER":
            continue
        chosen = None
        deadline = record["timestamp"] + timedelta(hours=72)
        for index, payment in payments.get(record.get("order_id"), []):
            timestamp = payment["timestamp"]
            if record["timestamp"] <= timestamp <= deadline:
                if (
                    chosen is None
                    or timestamp < chosen[1]["timestamp"]
                    or (
                        timestamp == chosen[1]["timestamp"]
                        and index < chosen[0]
                    )
                ):
                    chosen = (index, payment)
        if chosen is None:
            results.append({
                "order_id": record["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": record["order_id"],
                "status": "matched",
                "amount": chosen[1]["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") < 0
        ):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for match in matches:
        status = match["status"]
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

