"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if not s:
        return None

    parts = s.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or not all("0" <= char <= "9" for char in whole):
        return None
    if len(fraction) > 2 or (
        fraction and not all("0" <= char <= "9" for char in fraction)
    ):
        return None
    if len(parts) == 2 and not fraction:
        return None

    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)

    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3].strip()
    timestamp_text = fields[4].strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        chosen = None
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            amount = payment.get("amount")
            if (
                payment.get("order_id") != order.get("order_id")
                or not isinstance(amount, int)
                or isinstance(amount, bool)
                or amount < 0
            ):
                continue
            payment_time = payment.get("timestamp")
            order_time = order.get("timestamp")
            if payment_time < order_time or payment_time > order_time + timedelta(hours=72):
                continue
            if chosen is None or payment_time < chosen.get("timestamp"):
                chosen = payment

        if chosen is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": chosen.get("amount"),
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        else:
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_str, timestamp_str = fields

    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_type or not record_id or not order_id:
        return None

    if record_type == 'ORDER':
        if record_id != order_id:
            return None

    amount = parse_amount(amount_str.strip())
    if amount is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT' and record['amount'] >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        order_amount = order['amount']

        # Find eligible payments
        eligible_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and
            order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72)
        ]

        if eligible_payments:
            # Sort by timestamp, then by original order
            eligible_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            chosen_payment = eligible_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': chosen_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refund_total += abs(record['amount'])
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

