"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    value = s.strip()
    if not value:
        return None
    negative = value.startswith("-")
    digits = value[1:] if negative else value
    if not digits or digits.count(".") > 1:
        return None
    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if len(fraction) > 2 or (fraction and not fraction.isdigit()):
            return None
        fraction = fraction.ljust(2, "0")
    else:
        whole, fraction = digits, "00"
        if not whole.isdigit():
            return None
    cents = int(whole) * 100 + int(fraction)
    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = parse_amount(fields[3])
    timestamp_text = fields[4].strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if len(timestamp_text) != 16:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    payments = []
    orders = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            timestamp = record.get("timestamp")
            if isinstance(amount, int) and amount >= 0:
                payments.append(record)
        elif record.get("type") == "ORDER":
            orders.append(record)

    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None
        for payment in payments:
            if payment.get("order_id") != order_id:
                continue
            payment_time = payment.get("timestamp")
            if not isinstance(order_time, datetime) or not isinstance(payment_time, datetime):
                continue
            if order_time <= payment_time <= order_time + timedelta(hours=72):
                if chosen is None or payment_time < chosen.get("timestamp"):
                    chosen = payment
        if chosen is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen.get("amount"),
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    total = 0
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and isinstance(record.get("amount"), int)
                and record.get("amount") < 0):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = 0
    matched_total = 0
    unmatched_ids = []
    for result in matches:
        if not isinstance(result, dict):
            continue
        status = result.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        else:
            unmatched_ids.append(result.get("order_id"))
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

