"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    negative = s.startswith("-")
    digits = s[1:] if negative else s
    if not digits or digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not fraction or len(fraction) > 2:
            return None
    else:
        whole, fraction = digits, ""

    if not whole.isdigit() or (fraction and not fraction.isdigit()):
        return None

    try:
        cents = int(whole) * 100
        if fraction:
            cents += int(fraction) * (10 if len(fraction) == 1 else 1)
        return -cents if negative else cents
    except (ValueError, TypeError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    kind = fields[0].upper()
    if kind not in ("ORDER", "PAYMENT"):
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if not record_id or not order_id:
        return None
    if kind == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(fields[3])
    if amount is None or (kind == "ORDER" and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(fields[4], "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None

    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    payments = []
    for index, record in enumerate(records):
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") >= 0
            and isinstance(record.get("order_id"), str)
            and isinstance(record.get("timestamp"), datetime)
        ):
            payments.append((index, record))

    results = []
    for order in records:
        if (
            not isinstance(order, dict)
            or order.get("type") != "ORDER"
            or not isinstance(order.get("order_id"), str)
            or not isinstance(order.get("timestamp"), datetime)
        ):
            continue

        start = order["timestamp"]
        end = start + timedelta(hours=72)
        chosen = None

        for index, payment in payments:
            if (
                payment["order_id"] == order["order_id"]
                and start <= payment["timestamp"] <= end
            ):
                if chosen is None or (
                    payment["timestamp"],
                    index,
                ) < (
                    chosen["timestamp"],
                    chosen["_source_index"],
                ):
                    chosen = dict(payment)
                    chosen["_source_index"] = index

        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        else:
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

