"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if not re.fullmatch(r"[+-]?(?:\d+(?:\.\d{0,2})?|\.\d{1,2})", s):
        return None
    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []

    payments = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            continue
        order_id = record.get("order_id")
        timestamp = record.get("timestamp")
        payments.setdefault(order_id, []).append((timestamp, amount))

    results = []
    for record in records:
        if not isinstance(record, dict) or record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        order_time = record.get("timestamp")
        chosen = None

        if isinstance(order_time, datetime):
            end_time = order_time + timedelta(hours=72)
            for timestamp, amount in payments.get(order_id, []):
                if not isinstance(timestamp, datetime):
                    continue
                if order_time <= timestamp <= end_time:
                    if chosen is None or timestamp < chosen[0]:
                        chosen = (timestamp, amount)

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen[1],
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += abs(amount)
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if not s:
        return None

    sign = ""
    digits = s

    if digits[0] in "+-":
        sign = digits[0]
        digits = digits[1:]

    if not digits:
        return None

    parts = digits.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole.isdigit():
        return None

    if len(fraction) > 2 or (fraction and not fraction.isdigit()):
        return None

    try:
        amount = Decimal(sign + whole)
        if fraction:
            amount += Decimal(sign + "0." + fraction)
        return int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    type_field, record_id, order_id, amount_field, timestamp_field = fields
    record_type = type_field.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_field)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_field) != 16
        or timestamp_field[4] != "-"
        or timestamp_field[7] != "-"
        or timestamp_field[10] != " "
        or timestamp_field[13] != ":"
        or not all(
            timestamp_field[index].isdigit()
            for index in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15)
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_field, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        latest_time = order_time + timedelta(hours=72)
        chosen_payment = None

        for payment in records:
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue

            amount = payment.get("amount")
            payment_time = payment.get("timestamp")

            if not isinstance(amount, int) or isinstance(amount, bool):
                continue
            if amount < 0:
                continue
            if payment_time < order_time or payment_time > latest_time:
                continue

            if (
                chosen_payment is None
                or payment_time < chosen_payment.get("timestamp")
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for result in matches:
        status = result.get("status")

        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

