"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None
    if text[0] in "+-":
        digits = text[1:]
    else:
        digits = text
    if "." in digits:
        if digits.count(".") != 1:
            return None
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if not fraction or not fraction.isdigit() or len(fraction) > 2:
            return None
    else:
        whole = digits
        if not whole.isdigit():
            return None
    try:
        return int(Decimal(text) * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    type_text, record_id, order_id, amount_text, timestamp_text = fields
    record_type = type_text.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    if len(timestamp_text) != 16:
        return None
    if (timestamp_text[4] != "-" or timestamp_text[7] != "-" or
            timestamp_text[10] != " " or timestamp_text[13] != ":"):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    payments = [record for record in records
                if record.get("type") == "PAYMENT"
                and type(record.get("amount")) is int
                and record.get("amount") >= 0]
    for order in records:
        if order.get("type") != "ORDER":
            continue
        chosen = None
        for payment in payments:
            if payment.get("order_id") != order.get("order_id"):
                continue
            payment_time = payment.get("timestamp")
            order_time = order.get("timestamp")
            if not isinstance(payment_time, datetime) or not isinstance(order_time, datetime):
                continue
            if order_time <= payment_time <= order_time + timedelta(hours=72):
                if chosen is None or payment_time < chosen.get("timestamp"):
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": chosen.get("amount"),
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (record.get("type") == "PAYMENT" and
                type(record.get("amount")) is int and
                record["amount"] < 0):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

