"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None
    sign = -1 if s.startswith("-") else 1
    unsigned = s[1:] if s[:1] in "+-" else s
    if "." in unsigned:
        whole, fraction = unsigned.split(".")
    else:
        whole, fraction = unsigned, ""
    fraction = (fraction + "0")[:2]
    return sign * (int(whole) * 100 + int(fraction))


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text) is None:
        return None
    try:
        from datetime import datetime
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    from datetime import timedelta

    payments = {}
    for index, record in enumerate(records):
        if record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.setdefault(record["order_id"], []).append((index, record))

    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue
        best = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for index, payment in payments.get(order["order_id"], []):
            if order["timestamp"] <= payment["timestamp"] <= deadline:
                if best is None or payment["timestamp"] < best[1]["timestamp"]:
                    best = (index, payment)
        if best is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": best[1]["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if match["status"].lower() == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

