from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value[0] in "+-":
        digits = value[1:]
    else:
        digits = value

    if not digits or digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not fraction or len(fraction) > 2:
            return None
    else:
        whole = digits
        fraction = ""

    if not whole.isascii() or not whole.isdigit():
        return None
    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None

    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        return None

    return int(amount * 100)


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []

    for order in records:
        if order["type"] != "ORDER":
            continue

        deadline = order["timestamp"] + timedelta(hours=72)
        chosen_payment = None

        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if not (order["timestamp"] <= payment["timestamp"] <= deadline):
                continue

            if (
                chosen_payment is None
                or payment["timestamp"] < chosen_payment["timestamp"]
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            refund_total += abs(record["amount"])

    return refund_total


def build_summary(matches, refund_total):
    matched_amount = 0
    matched_count = 0
    unmatched_ids = []

    for result in matches:
        status = result["status"].casefold()

        if status == "matched":
            matched_count += 1
            matched_amount += result["amount"]
        elif status == "unmatched":
            unmatched_ids.append(result["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_amount - refund_total,
        "unmatched_ids": unmatched_ids,
    }

