from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if re.fullmatch(
        r"[+-]?(?:[0-9]+(?:\.[0-9]{1,2})?|\.[0-9]{1,2})",
        s,
    ) is None:
        return None

    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None

        fields = line.split("|")
        if len(fields) != 5:
            return None

        record_type, record_id, order_id, amount_text, timestamp_text = fields
        record_type = record_type.upper()
        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()
        if not record_id or not order_id:
            return None

        if record_type == "ORDER" and record_id != order_id:
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None

        if record_type == "ORDER" and amount < 0:
            return None

        if re.fullmatch(
            r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}",
            timestamp_text,
        ) is None:
            return None

        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, InvalidOperation):
        return None


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen_payment = None
        chosen_index = None

        for index, payment in enumerate(records):
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue
            if type(payment.get("amount")) is not int or payment["amount"] < 0:
                continue

            payment_time = payment.get("timestamp")
            if not isinstance(order_time, datetime) or not isinstance(
                payment_time, datetime
            ):
                continue

            if not (order_time <= payment_time <= order_time + timedelta(hours=72)):
                continue

            if (
                chosen_payment is None
                or payment_time < chosen_payment["timestamp"]
                or (
                    payment_time == chosen_payment["timestamp"]
                    and index < chosen_index
                )
            ):
                chosen_payment = payment
                chosen_index = index

        if chosen_payment is None:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": chosen_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and type(record.get("amount")) is int
            and record["amount"] < 0
        ):
            total += -record["amount"]

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")
        if isinstance(status, str) and status.casefold() == "matched":
            matched_count += 1
            net_total += result.get("amount", 0)
        elif isinstance(status, str) and status.casefold() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

