from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s[0] in "+-":
        digits = s[1:]
    else:
        digits = s

    if not digits:
        return None

    parts = digits.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or not all("0" <= char <= "9" for char in whole):
        return None
    if len(fraction) == 0 or len(fraction) > 2:
        return None
    if not all("0" <= char <= "9" for char in fraction):
        return None

    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) != 16:
        return None

    digit_positions = (
        list(range(0, 4))
        + list(range(5, 7))
        + list(range(8, 10))
        + list(range(11, 13))
        + list(range(14, 16))
    )
    if any(
        not ("0" <= timestamp_text[position] <= "9")
        for position in digit_positions
    ):
        return None
    if timestamp_text[4] != "-" or timestamp_text[7] != "-":
        return None
    if timestamp_text[10] != " " or timestamp_text[13] != ":":
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen_payment = None

        if order_time is not None:
            latest_time = order_time + timedelta(hours=72)

            for payment in records:
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue

                payment_amount = payment.get("amount")
                payment_time = payment.get("timestamp")

                if not isinstance(payment_amount, int) or payment_amount < 0:
                    continue
                if payment_time is None:
                    continue
