from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s[0] in "+-":
        digits = s[1:]
    else:
        digits = s

    if not digits:
        return None

    parts = digits.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or not all("0" <= char <= "9" for char in whole):
        return None
    if len(fraction) > 2 or (
        fraction and not all("0" <= char <= "9" for char in fraction)
    ):
        return None

    try:
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None

    cents = int(whole) * 100
    if fraction:
        cents += int(fraction.ljust(2, "0"))

    if s[0] == "-":
        cents = -cents

    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    payments = [
        record
        for record in records
        if (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] >= 0
        )
    ]

    for order in records:
        if order.get("type") != "ORDER":
            continue

        order_time = order["timestamp"]
        deadline = order_time + timedelta(hours=72)
        chosen_payment = None

        for payment in payments:
            if payment.get("order_id") != order.get("order_id"):
                continue

            payment_time = payment["timestamp"]
            if order_time <= payment_time <= deadline:
                if (
                    chosen_payment is None
                    or payment_time < chosen_payment["timestamp"]
                ):
                    chosen_payment = payment

        if chosen_payment is None:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order["order_id"],
                    "status": "matched",
                    "amount": chosen_payment["amount"],
                }
            )

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

