"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None
    if text[0] in "+-":
        digits = text[1:]
    else:
        digits = text
    if not digits or digits.count(".") > 1:
        return None
    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if len(fraction) > 2 or (fraction and not fraction.isdigit()):
            return None
    else:
        whole = digits
        fraction = ""
        if not whole.isdigit():
            return None
    sign = -1 if text.startswith("-") else 1
    cents = int(whole) * 100
    if fraction:
        cents += int(fraction.ljust(2, "0"))
    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    type_text, record_id, order_id, amount_text, timestamp_text = fields
    record_type = type_text.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    if records is None:
        return results
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None
        if order_id is not None and isinstance(order_time, datetime):
            deadline = order_time + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue
                amount = payment.get("amount")
                payment_time = payment.get("timestamp")
                if not isinstance(amount, int) or isinstance(amount, bool):
                    continue
                if amount < 0 or not isinstance(payment_time, datetime):
                    continue
                if payment_time < order_time or payment_time > deadline:
                    continue
                if chosen is None or payment_time < chosen.get("timestamp"):
                    chosen = {"timestamp": payment_time, "amount": amount}
        if chosen is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({"order_id": order_id, "status": "matched", "amount": chosen["amount"]})
    return results


def compute_refunds(records):
    if records is None:
        return 0
    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += abs(amount)
    return total


def build_summary(matches, refund_total):
    if matches is None:
        matches = []
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for result in matches:
        if not isinstance(result, dict):
            continue
        status = result.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                net_total += amount
        else:
            unmatched_ids.append(result.get("order_id"))
    net_total -= refund_total
    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

