"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    import re

    if not isinstance(s, str):
        return None
    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None
    sign = -1 if s.startswith("-") else 1
    if s[:1] in ("+", "-"):
        s = s[1:]
    if "." in s:
        whole, fraction = s.split(".", 1)
        fraction = (fraction + "0")[:2]
    else:
        whole, fraction = s, "00"
    return sign * (int(whole) * 100 + int(fraction))


def parse_record(line):
    import re

    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text) is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    if not isinstance(records, list):
        return results

    payments = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            timestamp = record.get("timestamp")
            if isinstance(amount, int) and amount >= 0:
                payments.append((record, timestamp))

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None

        if isinstance(order_time, datetime):
            deadline = order_time + timedelta(hours=72)
            for payment, payment_time in payments:
                if payment.get("order_id") != order_id:
                    continue
                if not isinstance(payment_time, datetime):
                    continue
                if order_time <= payment_time <= deadline:
                    if chosen is None or payment_time < chosen[1]:
                        chosen = (payment, payment_time)

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen[0].get("amount"),
            })
    return results


def compute_refunds(records):
    total = 0
    if not isinstance(records, list):
        return total
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0:
                total += abs(amount)
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches) if isinstance(matches, list) else 0
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    if isinstance(matches, list):
        for result in matches:
            if not isinstance(result, dict):
                continue
            status = result.get("status")
            if isinstance(status, str) and status.lower() == "matched":
                matched_count += 1
                amount = result.get("amount")
                if isinstance(amount, int):
                    net_total += amount
            else:
                unmatched_ids.append(result.get("order_id"))

    net_total -= refund_total
    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None

    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text) is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    payments = [
        record
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] >= 0
            and isinstance(record.get("timestamp"), datetime)
        )
    ]

    matches = []

    for order in records:
        if not (
            isinstance(order, dict)
            and order.get("type") == "ORDER"
            and isinstance(order.get("timestamp"), datetime)
        ):
            continue

        order_id = order.get("order_id")
        start = order["timestamp"]
        end = start + timedelta(hours=72)
        chosen = None

        for payment in payments:
            if payment.get("order_id") != order_id:
                continue

            payment_time = payment["timestamp"]
            if start <= payment_time <= end:
                if chosen is None or payment_time < chosen["timestamp"]:
                    chosen = payment

        if chosen is None:
            matches.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            matches.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })

    return matches


def compute_refunds(records):
    total = 0

    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")
        if not isinstance(status, str):
            continue

        status = status.casefold()

        if status == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int):
                matched_total += amount
        elif status == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

