"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]
    if not s:
        return None
    parts = s.split(".")
    if len(parts) > 2:
        return None
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole.isdigit():
        return None
    if len(parts) == 2 and (not fraction or not fraction.isdigit()):
        return None
    if len(fraction) > 2:
        return None
    fraction = fraction.ljust(2, "0")
    return sign * (int(whole) * 100 + int(fraction or "0"))


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []

    orders = []
    payments = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool) and amount >= 0:
                payments.append(record)

    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None

        for payment in payments:
            if payment.get("order_id") != order_id:
                continue
            payment_time = payment.get("timestamp")
            if not isinstance(order_time, datetime) or not isinstance(payment_time, datetime):
                continue
            if order_time <= payment_time <= order_time + timedelta(hours=72):
                if chosen is None or payment_time < chosen.get("timestamp"):
                    chosen = payment

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen.get("amount"),
            })

    return results


def compute_refunds(records):
    if not records:
        return 0

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
                total += abs(amount)
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if not isinstance(match, dict):
            continue
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = match.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                net_total += amount
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    net_total -= refund_total

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

