"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    text = s
    sign = 1
    if text[0] in "+-":
        if text[0] == "-":
            sign = -1
        text = text[1:]
    if not text:
        return None
    parts = text.split(".")
    if len(parts) > 2 or not parts[0]:
        return None
    if any(char < "0" or char > "9" for char in parts[0]):
        return None
    fraction = ""
    if len(parts) == 2:
        fraction = parts[1]
        if not fraction or len(fraction) > 2:
            return None
        if any(char < "0" or char > "9" for char in fraction):
            return None
    cents = int(parts[0]) * 100
    if fraction:
        cents += int(fraction.ljust(2, "0"))
    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    type_text, record_id, order_id, amount_text, timestamp_text = fields
    record_type = type_text.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None
    for index, character in enumerate(timestamp_text):
        if index not in (4, 7, 10, 13):
            if character < "0" or character > "9":
                return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    payments = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        timestamp = record.get("timestamp")
        order_id = record.get("order_id")
        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount >= 0
            and isinstance(timestamp, datetime)
        ):
            payments.setdefault(order_id, []).append(record)

    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None
        if isinstance(order_time, datetime):
            latest = order_time + timedelta(hours=72)
            for payment in payments.get(order_id, []):
                payment_time = payment["timestamp"]
                if order_time <= payment_time <= latest:
                    if chosen is None or payment_time < chosen["timestamp"]:
                        chosen = payment
        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    refund_total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            refund_total += -amount
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_str, timestamp_str = map(str.strip, fields)

    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    if not record_id or not order_id:
        return None

    if record_type == 'ORDER' and record_id != order_id:
        return None

    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT' and record['amount'] >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        end_time = order_timestamp + timedelta(hours=72)

        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= payment['timestamp'] <= end_time
        ]

        if qualifying_payments:
            # Sort by timestamp, then by original order
            qualifying_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            chosen_payment = qualifying_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': chosen_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

