"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]
    if not s:
        return None
    parts = s.split(".")
    if len(parts) > 2:
        return None
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or not whole.isdigit():
        return None
    if len(fraction) > 2 or (fraction and not fraction.isdigit()):
        return None
    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)
    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(fields[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    timestamp_text = fields[4]
    if (len(timestamp_text) != 16 or timestamp_text[4] != "-" or
            timestamp_text[7] != "-" or timestamp_text[10] != " " or
            timestamp_text[13] != ":" or
            not timestamp_text[:4].isdigit() or
            not timestamp_text[5:7].isdigit() or
            not timestamp_text[8:10].isdigit() or
            not timestamp_text[11:13].isdigit() or
            not timestamp_text[14:16].isdigit()):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    return {"type": record_type, "record_id": record_id,
            "order_id": order_id, "amount": amount, "timestamp": timestamp}


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    if not isinstance(records, (list, tuple)):
        return results
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None
        chosen_time = None
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT" or payment.get("order_id") != order_id:
                continue
            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if (not isinstance(amount, int) or isinstance(amount, bool) or
                    amount < 0 or not isinstance(order_time, datetime) or
                    not isinstance(payment_time, datetime)):
                continue
            if payment_time < order_time or payment_time > order_time + timedelta(hours=72):
                continue
            if chosen is None or payment_time < chosen_time:
                chosen = payment
                chosen_time = payment_time
        if chosen is None:
            results.append({"order_id": order_id, "status": "unmatched", "amount": 0})
        else:
            results.append({"order_id": order_id, "status": "matched",
                            "amount": chosen.get("amount")})
    return results


def compute_refunds(records):
    if not isinstance(records, (list, tuple)):
        return 0
    total = 0
    for record in records:
        if not isinstance(record, dict) or record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += -amount
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for match in matches:
        if not isinstance(match, dict):
            continue
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))
    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_str, timestamp_str = map(str.strip, fields)

    record_type = record_type.upper()
    if record_type not in {'ORDER', 'PAYMENT'}:
        return None

    if not record_id or not order_id:
        return None

    if record_type == 'ORDER' and record_id != order_id:
        return None

    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    orders = []
    payments = []

    # Separate orders and payments
    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT' and record['amount'] >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        order_amount = order['amount']

        # Find qualifying payments
        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72)
        ]

        if qualifying_payments:
            # Sort by timestamp and select the earliest
            qualifying_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            chosen_payment = qualifying_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': chosen_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

