from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    sign = -1 if s.startswith("-") else 1
    digits = s[1:] if s.startswith(("+", "-")) else s
    if digits.count(".") > 1:
        return None
    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not fraction or len(fraction) > 2:
            return None
    else:
        whole, fraction = digits, ""
    if not whole or not all("0" <= c <= "9" for c in whole):
        return None
    if fraction and not all("0" <= c <= "9" for c in fraction):
        return None
    try:
        cents = int(whole) * 100
        if len(fraction) == 1:
            cents += int(fraction) * 10
        elif len(fraction) == 2:
            cents += int(fraction)
        return sign * cents
    except (TypeError, ValueError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order.get("type") != "ORDER":
            continue
        chosen = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for payment in records:
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            if payment.get("amount") < 0:
                continue
            payment_time = payment.get("timestamp")
            if payment_time < order["timestamp"] or payment_time > deadline:
                continue
            if chosen is None or payment_time < chosen.get("timestamp"):
                chosen = payment
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") < 0
        ):
            total += abs(record.get("amount"))
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        else:
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

