def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    if s[0] in "+-":
        sign = -1 if s[0] == "-" else 1
        number = s[1:]
    else:
        sign = 1
        number = s

    if not number or number.count(".") > 1:
        return None

    if "." in number:
        whole, fraction = number.split(".")
        if not whole or not fraction or len(fraction) > 2:
            return None
    else:
        whole = number
        fraction = ""

    if not whole.isascii() or not whole.isdigit():
        return None
    if fraction and (not fraction.isascii() or not fraction.isdigit()):
        return None

    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)

    return sign * cents


