"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount, timestamp = map(str.strip, fields)
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT'] or not record_id or not order_id:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    amount_cents = parse_amount(amount)
    if amount_cents is None or (record_type == 'ORDER' and amount_cents < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record:
            records.append(record)
    return records


def match_payments(records):
    results = []
    payments = {}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] >= 0:
            payments.setdefault(record['order_id'], []).append(record)

    for record in records:
        if record['type'] == 'ORDER':
            order_id = record['order_id']
            matched_payment = None

            if order_id in payments:
                for payment in payments[order_id]:
                    if record['timestamp'] <= payment['timestamp'] <= record['timestamp'] + timedelta(hours=72):
                        if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                            matched_payment = payment

            if matched_payment:
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': matched_payment['amount']
                })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })

    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if isinstance(s, str):
        try:
            amount = Decimal(s)
            return int(amount * 100)
        except (InvalidOperation, ValueError):
            return None
    return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_str, timestamp_str = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount_str.strip())

    if not record_id or not order_id or amount is None:
        return None

    if record_type == 'ORDER':
        if record_id != order_id:
            return None
        if amount < 0:
            return None
    elif record_type == 'PAYMENT':
        if amount > 0:
            return None
    else:
        return None

    try:
        timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT' and record['amount'] >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        order_amount = order['amount']

        # Find payments that match the criteria
        qualifying_payments = [
            payment for payment in payments
            if (payment['order_id'] == order_id and
                order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72))
        ]

        if qualifying_payments:
            # Sort by timestamp and then by original order
            qualifying_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            chosen_payment = qualifying_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': chosen_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refund_total += abs(record['amount'])
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

