"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]
    if not s:
        return None
    parts = s.split(".")
    if len(parts) > 2:
        return None
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or any(ch < "0" or ch > "9" for ch in whole):
        return None
    if len(fraction) > 2 or any(ch < "0" or ch > "9" for ch in fraction):
        return None
    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)
    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type = fields[0].strip().upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(fields[3])
    if amount is None:
        return None
    try:
        timestamp = datetime.strptime(fields[4], "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if record_type == "ORDER" and amount < 0:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue
        chosen = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if order["timestamp"] <= payment["timestamp"] <= deadline:
                if chosen is None or payment["timestamp"] < chosen["timestamp"]:
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for match in matches:
        status = str(match["status"]).lower()
        if status == "matched":
            matched_count += 1
            net_total += match["amount"]
        elif status == "unmatched":
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if not re.fullmatch(r"[+-]?(?:\d+(?:\.\d{1,2})?|\.\d{1,2})", s):
        return None

    negative = s.startswith("-")
    unsigned = s[1:] if s[:1] in "+-" else s

    if "." in unsigned:
        whole, fraction = unsigned.split(".", 1)
    else:
        whole, fraction = unsigned, ""

    if not whole:
        whole = "0"

    cents = int(whole) * 100 + int(fraction.ljust(2, "0") or "0")
    return -cents if negative else cents


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None

        fields = line.split("|")
        if len(fields) != 5:
            return None

        record_type, record_id, order_id, amount_text, timestamp_text = fields
        record_type = record_type.upper()
        record_id = record_id.strip()
        order_id = order_id.strip()

        if record_type not in ("ORDER", "PAYMENT"):
            return None

        if not record_id or not order_id:
            return None

        if record_type == "ORDER" and record_id != order_id:
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None

        if record_type == "ORDER" and amount < 0:
            return None

        if not re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text):
            return None

        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "timestamp": timestamp,
        }
    except Exception:
        return None


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    if not isinstance(records, list):
        return results

    payments = []
    for source_index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        timestamp = record.get("timestamp")

        if (
            isinstance(amount, int)
            and not isinstance(amount, bool)
            and amount >= 0
            and isinstance(timestamp, datetime)
        ):
            payments.append((source_index, record))

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        order_timestamp = record.get("timestamp")
        chosen_payment = None

        if isinstance(order_timestamp, datetime):
            deadline = order_timestamp + timedelta(hours=72)
            qualifying = []

            for source_index, payment in payments:
                if payment.get("order_id") != order_id:
                    continue

                payment_timestamp = payment["timestamp"]
                if order_timestamp <= payment_timestamp <= deadline:
                    qualifying.append((payment_timestamp, source_index, payment))

            if qualifying:
                qualifying.sort(key=lambda item: (item[0], item[1]))
                chosen_payment = qualifying[0][2]

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += abs(amount)

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")

        if isinstance(status, str) and status.casefold() == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif isinstance(status, str) and status.casefold() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

