"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if s == "":
        return None

    sign = 1
    if s[0] in ("+", "-"):
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if s == "" or s.count(".") > 1:
        return None

    if "." in s:
        whole, fraction = s.split(".")
        if whole == "" or not whole.isdigit():
            return None
        if fraction == "" or not fraction.isdigit() or len(fraction) > 2:
            return None
    else:
        whole = s
        fraction = ""
        if not whole.isdigit():
            return None

    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)

    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(fields[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    timestamp_text = fields[4]
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []

    if not isinstance(records, (list, tuple)):
        return []

    for record in records:
        if not isinstance(record, dict):
            continue
        record_type = record.get("type")
        if record_type == "ORDER":
            orders.append(record)
        elif record_type == "PAYMENT":
            amount = record.get("amount")
            if (
                isinstance(amount, int)
                and not isinstance(amount, bool)
                and amount >= 0
            ):
                payments.append(record)

    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None

        if isinstance(order_time, datetime):
            latest = order_time + timedelta(hours=72)
            for payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue
                if order_time <= payment_time <= latest:
                    if chosen is None or payment_time < chosen.get("timestamp"):
                        chosen = payment

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen.get("amount"),
            })

    return results


def compute_refunds(records):
    total = 0
    if not isinstance(records, (list, tuple)):
        return 0

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += -amount

    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, (list, tuple)):
        matches = []

    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue
        status = result.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = result.get("amount")
            if isinstance(amount, int) and not isinstance(amount, bool):
                matched_total += amount
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

