"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if s.startswith("-"):
        sign, value = -1, s[1:]
    elif s.startswith("+"):
        sign, value = 1, s[1:]
    else:
        sign, value = 1, s
    if not value:
        return None
    parts = value.split(".")
    if len(parts) > 2:
        return None
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or not whole.isdigit():
        return None
    if len(fraction) > 2 or (fraction and not fraction.isdigit()):
        return None
    fraction = fraction.ljust(2, "0")
    return sign * (int(whole) * 100 + (int(fraction) if fraction else 0))


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    if record_type not in ("ORDER", "PAYMENT") or not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(fields[3])
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(fields[4].strip(), "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None and record["record_id"] not in seen:
            records.append(record)
            seen.add(record["record_id"])
    return records


def match_payments(records):
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        chosen = None
        deadline = order["timestamp"] + timedelta(hours=72)
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            if not isinstance(payment.get("amount"), int) or payment["amount"] < 0:
                continue
            timestamp = payment.get("timestamp")
            if not isinstance(timestamp, datetime):
                continue
            if order["timestamp"] <= timestamp <= deadline:
                if chosen is None or timestamp < chosen["timestamp"]:
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") < 0
        ):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for match in matches:
        if not isinstance(match, dict):
            continue
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if not re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s):
        return None

    try:
        amount = Decimal(s) * 100
        return int(amount)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if not re.fullmatch(
        r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    payments = [
        record
        for record in records
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and record.get("amount", -1) >= 0
        )
    ]

    matches = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        latest_timestamp = order_timestamp + timedelta(hours=72)

        chosen_payment = None

        for payment in payments:
            if payment.get("order_id") != order_id:
                continue

            payment_timestamp = payment.get("timestamp")
            if not (
                order_timestamp <= payment_timestamp <= latest_timestamp
            ):
                continue

            if (
                chosen_payment is None
                or payment_timestamp < chosen_payment["timestamp"]
            ):
                chosen_payment = payment

        if chosen_payment is None:
            matches.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            matches.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": chosen_payment["amount"],
                }
            )

    return matches


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            refund_total += abs(record["amount"])

    return refund_total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")
        if isinstance(status, str) and status.casefold() == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif (
            isinstance(status, str)
            and status.casefold() == "unmatched"
        ):
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

