"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if not s:
        return None

    parts = s.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or not whole.isdigit():
        return None
    if len(fraction) > 2 or (fraction and not fraction.isdigit()):
        return None

    fraction = fraction.ljust(2, "0")
    return sign * (int(whole) * 100 + int(fraction or "0"))


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    payments = [
        record for record in records
        if record.get("type") == "PAYMENT"
        and record.get("amount", 0) >= 0
    ]
    results = []

    for order in records:
        if order.get("type") != "ORDER":
            continue

        order_time = order["timestamp"]
        latest_time = order_time + timedelta(hours=72)
        chosen = None

        for payment in payments:
            if payment.get("order_id") != order.get("order_id"):
                continue
            payment_time = payment["timestamp"]
            if order_time <= payment_time <= latest_time:
                if chosen is None or payment_time < chosen["timestamp"]:
                    chosen = payment

        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record.get("type") == "PAYMENT" and record.get("amount", 0) < 0:
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if str(match.get("status", "")).lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        else:
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

