"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if not re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s):
        return None
    try:
        whole, dot, fraction = s.partition(".")
        sign = -1 if whole.startswith("-") else 1
        digits = whole.lstrip("+-")
        cents = int(digits) * 100
        if dot:
            cents += int(fraction.ljust(2, "0"))
        return sign * cents
    except (ValueError, InvalidOperation):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None

    type_text, record_id, order_id, amount_text, timestamp_text = fields
    record_type = type_text.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    seen = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in seen:
            continue
        seen.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []

    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        chosen = None
        deadline = order.get("timestamp") + timedelta(hours=72)
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            amount = payment.get("amount")
            timestamp = payment.get("timestamp")
            if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
                continue
            if timestamp < order.get("timestamp") or timestamp > deadline:
                continue
            if chosen is None or timestamp < chosen["timestamp"]:
                chosen = payment

        if chosen is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0

    total = 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") != "PAYMENT":
            continue
        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += abs(amount)
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches) if isinstance(matches, list) else 0
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    if not isinstance(matches, list):
        matches = []

    for match in matches:
        if not isinstance(match, dict):
            continue
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = match.get("amount", 0)
            if isinstance(amount, int) and not isinstance(amount, bool):
                net_total += amount
        else:
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    if not isinstance(refund_total, int) or isinstance(refund_total, bool):
        refund_total = 0

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

