from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        if amount.as_tuple().exponent < -2 or amount.as_tuple().exponent > 0:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount_str, timestamp_str = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    amount = parse_amount(amount_str)
    if amount is None and (record_type == 'ORDER' and amount < 0):
        return None
    timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record

    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order = orders[order_id]
                if order['timestamp'] <= record['timestamp'] <= order['timestamp'] + timedelta(hours=72):
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue
        results.append({
            'order_id': order_id,
            'status': 'unmatched',
            'amount': 0
        })

    return results


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_str, timestamp_str = map(str.strip, fields)

    record_type = record_type.upper()
    if record_type not in {'ORDER', 'PAYMENT'}:
        return None

    if not record_id or not order_id:
        return None

    if record_type == 'ORDER' and record_id != order_id:
        return None

    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    orders = []
    payments = []

    # Separate orders and payments
    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT' and record['amount'] >= 0:
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        end_time = order_timestamp + timedelta(hours=72)

        # Filter payments that match the criteria
        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= payment['timestamp'] <= end_time
        ]

        if qualifying_payments:
            # Sort by timestamp, then by original order
            qualifying_payments.sort(key=lambda p: (p['timestamp'], payments.index(p)))
            chosen_payment = qualifying_payments[0]
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': chosen_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refund_total += abs(record['amount'])
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

