"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    start = 1 if s[0] in "+-" else 0
    body = s[start:]
    if not body:
        return None
    parts = body.split(".")
    if len(parts) > 2:
        return None
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or not whole.isdigit():
        return None
    if len(fraction) > 2 or (fraction and not fraction.isdigit()):
        return None
    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)
    return -cents if s[0] == "-" else cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    type_text, record_id, order_id, amount_text, timestamp_text = fields
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    record_type = type_text.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue
        chosen = None
        latest = order["timestamp"] + timedelta(hours=72)
        for payment in records:
            if payment["type"] != "PAYMENT":
                continue
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["amount"] < 0:
                continue
            if order["timestamp"] <= payment["timestamp"] <= latest:
                if chosen is None or payment["timestamp"] < chosen["timestamp"]:
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for match in matches:
        status = match["status"]
        if status.lower() == "matched":
            matched_count += 1
            matched_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    if s[0] in "+-":
        sign = -1 if s[0] == "-" else 1
        s = s[1:]
    else:
        sign = 1

    if s.count(".") > 1 or s == ".":
        return None

    if "." in s:
        whole, fraction = s.split(".")
        if (whole and not whole.isdigit()) or (
            fraction and not fraction.isdigit()
        ):
            return None
        if len(fraction) > 2 or (not whole and not fraction):
            return None
    else:
        whole = s
        fraction = ""

    if not whole and not fraction:
        return None

    try:
        cents = int((whole or "0") + fraction.ljust(2, "0"))
    except (TypeError, ValueError):
        return None

    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    type_text, record_id, order_id, amount_text, timestamp_text = fields
    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None

    record_type = type_text.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
        or not all(
            timestamp_text[index].isdigit()
            for index in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15)
        )
    ):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError, OverflowError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        latest_time = order_time + timedelta(hours=72)

        chosen_payment = None

        for payment in records:
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue

            amount = payment.get("amount")
            if not isinstance(amount, int) or isinstance(amount, bool):
                continue
            if amount < 0:
                continue

            payment_time = payment.get("timestamp")
            if payment_time < order_time or payment_time > latest_time:
                continue

            if (
                chosen_payment is None
                or payment_time < chosen_payment.get("timestamp")
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")
        if isinstance(status, str):
            status = status.lower()
        else:
            status = ""

        if status == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif status == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

