"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    if s[0] in "+-":
        digits = s[1:]
    else:
        digits = s
    if not digits:
        return None
    parts = digits.split(".")
    if len(parts) > 2 or not parts[0].isdigit():
        return None
    if len(parts) == 2:
        fraction = parts[1]
        if not 1 <= len(fraction) <= 2 or not fraction.isdigit():
            return None
    else:
        fraction = ""
    cents = int(parts[0]) * 100
    if fraction:
        cents += int(fraction) * (10 if len(fraction) == 1 else 1)
    if s[0] == "-":
        cents = -cents
    return cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount_text, timestamp_text = fields
    if record_type.lower() not in ("order", "payment"):
        return None
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    results = []
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        chosen = None
        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            amount = payment.get("amount")
            timestamp = payment.get("timestamp")
            order_timestamp = order.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if not isinstance(timestamp, datetime) or not isinstance(order_timestamp, datetime):
                continue
            if timestamp < order_timestamp:
                continue
            if timestamp > order_timestamp + timedelta(hours=72):
                continue
            if chosen is None or timestamp < chosen.get("timestamp"):
                chosen = payment
        if chosen is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": chosen.get("amount"),
            })
    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") < 0
        ):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for match in matches:
        if not isinstance(match, dict):
            continue
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = match.get("amount")
            if isinstance(amount, int):
                matched_total += amount
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    if not isinstance(refund_total, int):
        refund_total = 0

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

