from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    value = s.strip()
    if not value:
        return None

    if value[0] in "+-":
        digits = value[1:]
    else:
        digits = value

    if digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if len(fraction) > 2 or not fraction.isdigit():
            return None
    elif not digits.isdigit():
        return None

    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        return None

    return int(amount * 100)


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    if not isinstance(records, list):
        return results

    for order in records:
        if not isinstance(order, dict):
            continue
        if order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        deadline = order_time + timedelta(hours=72)

        chosen_payment = None

        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue

            amount = payment.get("amount")
            payment_time = payment.get("timestamp")

            if not isinstance(amount, int) or amount < 0:
                continue
            if not isinstance(payment_time, datetime):
                continue
            if order_time <= payment_time <= deadline:
                if chosen_payment is None:
                    chosen_payment = payment
                elif payment_time < chosen_payment.get("timestamp"):
                    chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    if not isinstance(records, list):
        return total

    for record in records:
        if not isinstance(record, dict):
            continue

        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0:
                total += abs(amount)

    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []

    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        if not isinstance(result, dict):
            continue

        status = result.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int):
                matched_total += amount
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

