"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None
    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    parts = line.split("|")
    if len(parts) != 5:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount_text = parts[3]
    timestamp_text = parts[4]

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text) is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    for order in records:
        if order.get("type") != "ORDER":
            continue

        chosen = None
        order_time = order["timestamp"]
        latest = order_time + timedelta(hours=72)

        for payment in records:
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue
            if payment.get("amount", -1) < 0:
                continue

            payment_time = payment["timestamp"]
            if order_time <= payment_time <= latest:
                if chosen is None or payment_time < chosen["timestamp"]:
                    chosen = payment

        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record.get("type") == "PAYMENT" and record.get("amount", 0) < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

