  "rules": [
    {
      "id": "P5-L1",
      "quote": "Implement `match_payments(records)` to produce reconciliation results for parsed records."
    },
    {
      "id": "P5-L2",
      "quote": "- Produce one result for every `ORDER`, following order-record source order."
    },
    {
      "id": "P5-L3",
      "quote": "- Associate only non-negative `PAYMENT` records by `order_id`;"
    },
    {
      "id": "P5-L4",
      "quote": "refunds never match."
    },
    {
      "id": "P5-L5",
      "quote": "- A payment qualifies only when its timestamp is at or after the order timestamp and no later than exactly 72 hours afterward;"
    },
    {
      "id": "P5-L6",
      "quote": "both endpoints are included."
    },
    {
      "id": "P5-L7",
      "quote": "- If several payments qualify, choose the earliest timestamp and retain source order for an exact timestamp tie."
    },
    {
      "id": "P5-L8",
      "quote": "- Each result is a dictionary with exactly `order_id`, `status`, and `amount`."
    },
    {
      "id": "P5-L9",
      "quote": "- Status must communicate `matched` or `unmatched`, with no case requirement."
    },
    {
