"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not text:
        return None

    if text[0] in "+-":
        digits = text[1:]
    else:
        digits = text

    if not digits or digits.count(".") > 1:
        return None

    if "." in digits:
        whole, fraction = digits.split(".")
        if not whole or not whole.isdigit():
            return None
        if not fraction or len(fraction) > 2 or not fraction.isdigit():
            return None
    else:
        whole = digits
        if not whole.isdigit():
            return None

    try:
        value = Decimal(text)
    except (InvalidOperation, ValueError):
        return None
    if value.as_tuple().exponent < -2:
        return None
    return int(value * 100)


def parse_record(line):
    if not isinstance(line, str):
        return None
    parts = line.split("|")
    if len(parts) != 5:
        return None

    record_type = parts[0].upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = parts[1].strip()
    order_id = parts[2].strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(parts[3])
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None

    timestamp_text = parts[4]
    if (len(timestamp_text) != 16 or timestamp_text[4] != "-"
            or timestamp_text[7] != "-" or timestamp_text[10] != " "
            or timestamp_text[13] != ":"):
