"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None

    try:
        sign = -1 if s.startswith("-") else 1
        digits = s[1:] if s[:1] in "+-" else s

        if "." in digits:
            whole, fraction = digits.split(".")
        else:
            whole, fraction = digits, ""

        cents = int(whole) * 100 + int(fraction.ljust(2, "0") or "0")
        return sign * cents
    except (ValueError, OverflowError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None

        fields = line.split("|")
        if len(fields) != 5:
            return None

        record_type, record_id, order_id, amount_text, timestamp_text = fields
        record_type = record_type.upper()

        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()

        if not record_id or not order_id:
            return None

        if record_type == "ORDER" and record_id != order_id:
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None

        if record_type == "ORDER" and amount < 0:
            return None

        if re.fullmatch(
            r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}",
            timestamp_text
        ) is None:
            return None

        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    payments_by_order = {}

    for record in records:
        if not isinstance(record, dict):
            continue

        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        order_id = record.get("order_id")
        timestamp = record.get("timestamp")

        if type(amount) is not int or amount < 0:
            continue

        if not isinstance(order_id, str) or not isinstance(timestamp, datetime):
            continue

        payments_by_order.setdefault(order_id, []).append(record)

    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        chosen_payment = None

        if isinstance(order_id, str) and isinstance(order_timestamp, datetime):
            latest_timestamp = order_timestamp + timedelta(hours=72)

            for payment in payments_by_order.get(order_id, []):
                payment_timestamp = payment["timestamp"]

                if (
                    order_timestamp <= payment_timestamp <= latest_timestamp
                    and (
                        chosen_payment is None
                        or payment_timestamp < chosen_payment["timestamp"]
                    )
                ):
                    chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if type(amount) is int and amount < 0:
            total += abs(amount)

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

