    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(
            timestamp_text.strip(), "%Y-%m-%d %H:%M"
        )
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


