"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    text = s.strip()
    if not text:
        return None

    negative = text.startswith("-")
    number = text[1:] if negative else text
    if not number:
        return None

    parts = number.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or not whole.isdigit():
        return None
    if len(fraction) > 2 or (fraction and not fraction.isdigit()):
        return None

    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)

    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = parse_amount(fields[3])
    timestamp_text = fields[4].strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []

    if not isinstance(records, list):
        return results

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_timestamp = order.get("timestamp")
        if not isinstance(order_timestamp, datetime):
            continue

        deadline = order_timestamp + timedelta(hours=72)
        chosen = None

        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order.get("order_id"):
                continue

            amount = payment.get("amount")
            timestamp = payment.get("timestamp")
            if not isinstance(amount, int) or amount < 0:
                continue
            if not isinstance(timestamp, datetime):
                continue
            if timestamp < order_timestamp or timestamp > deadline:
                continue

            if chosen is None or timestamp < chosen["timestamp"]:
                chosen = payment

        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    if not isinstance(records, list):
        return total

    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record.get("amount") < 0
        ):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    total_orders = 0
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    if isinstance(matches, list):
        total_orders = len(matches)

        for match in matches:
            if not isinstance(match, dict):
                continue

            status = match.get("status")
            if isinstance(status, str) and status.lower() == "matched":
                matched_count += 1
                amount = match.get("amount")
                if isinstance(amount, int):
                    net_total += amount
            else:
                unmatched_ids.append(match.get("order_id"))

    if isinstance(refund_total, int):
        net_total -= refund_total

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

