"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    digits = s[1:] if s.startswith("-") else s
    if not digits:
        return None
    parts = digits.split(".")
    if len(parts) > 2 or not parts[0].isdigit():
        return None
    if len(parts) == 2 and (not parts[1].isdigit() or len(parts[1]) > 2):
        return None
    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    if record_type not in ("ORDER", "PAYMENT") or not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    if timestamp.strftime("%Y-%m-%d %H:%M") != timestamp_text:
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    record_ids = set()
    for line in text.splitlines():
        record = parse_record(line)
        if record is None or record["record_id"] in record_ids:
            continue
        record_ids.add(record["record_id"])
        records.append(record)
    return records


def match_payments(records):
    if not isinstance(records, list):
        return []
    payments = []
    orders = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            orders.append(record)
        elif (record.get("type") == "PAYMENT"
              and isinstance(record.get("amount"), int)
              and record["amount"] >= 0):
            payments.append(record)

    results = []
    for order in orders:
        chosen = None
        earliest = order.get("timestamp")
        latest = earliest + timedelta(hours=72)
        for payment in payments:
            if payment.get("order_id") != order.get("order_id"):
                continue
            timestamp = payment.get("timestamp")
            if timestamp < earliest or timestamp > latest:
                continue
            if chosen is None or timestamp < chosen.get("timestamp"):
                chosen = payment
        if chosen is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": chosen["amount"],
            })
    return results


def compute_refunds(records):
    total = 0
    if not isinstance(records, list):
        return total
    for record in records:
        if (isinstance(record, dict)
                and record.get("type") == "PAYMENT"
                and isinstance(record.get("amount"), int)
                and record["amount"] < 0):
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for match in matches:
        if str(match["status"]).lower() == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

