"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None

    sign = 1
    start = 0
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        start = 1

    body = s[start:]
    if not body:
        return None

    parts = body.split(".")
    if len(parts) > 2:
        return None

    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""

    if not whole or any(ch < "0" or ch > "9" for ch in whole):
        return None
    if len(fraction) > 2 or any(ch < "0" or ch > "9" for ch in fraction):
        return None

    fraction = fraction.ljust(2, "0")
    return sign * (int(whole) * 100 + int(fraction or "0"))


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_text = fields[3].strip()
    timestamp_text = fields[4].strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    if len(timestamp_text) != 16:
        return None
    if (timestamp_text[4] != "-" or timestamp_text[7] != "-" or
            timestamp_text[10] != " " or timestamp_text[13] != ":"):
        return None
    for index, char in enumerate(timestamp_text):
        if index not in (4, 7, 10, 13) and not char.isdigit():
            return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    identifiers = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue
        if record["record_id"] in identifiers:
            continue
        records.append(record)
        identifiers.add(record["record_id"])

    return records


def match_payments(records):
    if not isinstance(records, list):
        return []

    orders = []
    payments = []

    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            orders.append(record)
        elif record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if type(amount) is int and amount >= 0:
                payments.append(record)

    results = []
    for order in orders:
        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None

        if isinstance(order_time, datetime):
            deadline = order_time + timedelta(hours=72)
            for payment in payments:
                if payment.get("order_id") != order_id:
                    continue
                payment_time = payment.get("timestamp")
                if not isinstance(payment_time, datetime):
                    continue
                if order_time <= payment_time <= deadline:
                    if chosen is None or payment_time < chosen.get("timestamp"):
                        chosen = payment

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen.get("amount"),
            })

    return results


def compute_refunds(records):
    if not isinstance(records, list):
        return 0

    total = 0
    for record in records:
        if (isinstance(record, dict) and
                record.get("type") == "PAYMENT" and
                isinstance(record.get("amount"), int) and
                record["amount"] < 0):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    if not isinstance(matches, list):
        matches = []

    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        if not isinstance(match, dict):
            continue
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = match.get("amount")
            if isinstance(amount, int):
                net_total += amount
        else:
            unmatched_ids.append(match.get("order_id"))

    if not isinstance(refund_total, int):
        refund_total = 0

    unmatched_ids.sort()
    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

