    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if s == "" or s.count(".") > 1:
        return None

    if "." in s:
        whole, fraction = s.split(".")
        if fraction == "" or len(fraction) > 2:
            return None
    else:
        whole = s
        fraction = ""

    if whole == "" or not all("0" <= char <= "9" for char in whole):
