from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None

    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        latest_timestamp = order_timestamp + timedelta(hours=72)

        chosen_payment = None

        for payment in records:
            if not isinstance(payment, dict):
                continue
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue

            amount = payment.get("amount")
            if not isinstance(amount, int) or isinstance(amount, bool):
                continue
            if amount < 0:
                continue

            payment_timestamp = payment.get("timestamp")
            if payment_timestamp < order_timestamp:
                continue
            if payment_timestamp > latest_timestamp:
                continue

            if (
                chosen_payment is None
                or payment_timestamp < chosen_payment.get("timestamp")
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += abs(amount)

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")

        if isinstance(status, str) and status.casefold() == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif isinstance(status, str) and status.casefold() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

