"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if not s or s.startswith("+"):
        return None
    if s.startswith("-"):
        digits = s[1:]
        sign = -1
    else:
        digits = s
        sign = 1
    if not digits:
        return None
    parts = digits.split(".")
    if len(parts) > 2:
        return None
    whole = parts[0]
    fraction = parts[1] if len(parts) == 2 else ""
    if not whole or not whole.isdigit():
        return None
    if len(fraction) > 2 or (fraction and not fraction.isdigit()):
        return None
    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)
    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = parse_amount(fields[3])

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id or amount is None:
        return None
    if record_type == "ORDER":
        if record_id != order_id or amount < 0:
            return None

    try:
        timestamp = datetime.strptime(fields[4], "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    if not isinstance(records, list):
        return results

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        chosen = None

        if order_time is not None:
            latest = order_time + timedelta(hours=72)
            for payment in records:
                if not isinstance(payment, dict):
                    continue
                if payment.get("type") != "PAYMENT":
                    continue
                if payment.get("order_id") != order_id:
                    continue

                amount = payment.get("amount")
                payment_time = payment.get("timestamp")
                if not isinstance(amount, int) or amount < 0:
                    continue
                if payment_time < order_time or payment_time > latest:
                    continue
                if chosen is None or payment_time < chosen.get("timestamp"):
                    chosen = payment

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen.get("amount"),
            })

    return results


def compute_refunds(records):
    total = 0
    if not isinstance(records, list):
        return 0
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "PAYMENT":
            amount = record.get("amount")
            if isinstance(amount, int) and amount < 0:
                total += abs(amount)
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches) if isinstance(matches, list) else 0
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    if isinstance(matches, list):
        for match in matches:
            if not isinstance(match, dict):
                continue
            status = match.get("status")
            if isinstance(status, str) and status.lower() == "matched":
                matched_count += 1
                amount = match.get("amount")
                if isinstance(amount, int):
                    matched_total += amount
            elif isinstance(status, str) and status.lower() == "unmatched":
                unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if not re.fullmatch(r"[+-]?[0-9]+(?:\.[0-9]{1,2})?", s):
        return None

    negative = s.startswith("-")
    if s[0] in "+-":
        s = s[1:]

    if "." in s:
        whole, fraction = s.split(".", 1)
    else:
        whole, fraction = s, ""

    cents = int(whole) * 100
    cents += int(fraction.ljust(2, "0")) if fraction else 0

    return -cents if negative else cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id:
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    if not re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text):
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or not text:
        return []

    records = []
    record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        if record["record_id"] in record_ids:
            continue

        record_ids.add(record["record_id"])
        records.append(record)

    return records


def match_payments(records):
    payments_by_order = {}

    for source_index, record in enumerate(records):
        if (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] >= 0
            and isinstance(record.get("timestamp"), datetime)
        ):
            order_id = record.get("order_id")
            payments_by_order.setdefault(order_id, []).append(
                (record["timestamp"], source_index, record["amount"])
            )

    results = []

    for record in records:
        if record.get("type") != "ORDER":
            continue

        order_id = record.get("order_id")
        order_timestamp = record.get("timestamp")
        chosen_payment = None

        if isinstance(order_timestamp, datetime):
            end_timestamp = order_timestamp + timedelta(hours=72)

            for payment_timestamp, source_index, payment_amount in payments_by_order.get(
                order_id, []
            ):
                if order_timestamp <= payment_timestamp <= end_timestamp:
                    candidate = (
                        payment_timestamp,
                        source_index,
                        payment_amount,
                    )
                    if chosen_payment is None or candidate[:2] < chosen_payment[:2]:
                        chosen_payment = candidate

        if chosen_payment is None:
            results.append(
                {
                    "order_id": order_id,
                    "status": "unmatched",
                    "amount": 0,
                }
            )
        else:
            results.append(
                {
                    "order_id": order_id,
                    "status": "matched",
                    "amount": chosen_payment[2],
                }
            )

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] < 0
        ):
            refund_total += abs(record["amount"])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")
        if isinstance(status, str) and status.casefold() == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif isinstance(status, str) and status.casefold() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    return {
