            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] >= 0
        ):
            payments_by_order.setdefault(record.get("order_id"), []).append(record)

    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        latest_timestamp = order_timestamp + timedelta(hours=72)

        chosen_payment = None

        for payment in payments_by_order.get(order_id, []):
            payment_timestamp = payment.get("timestamp")

            if (
