"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or not s:
        return None
    value = s
    if value[0] in "+-":
        value = value[1:]
    if not value:
        return None
    parts = value.split(".")
    if len(parts) > 2:
        return None
    if not parts[0] or any(c not in "0123456789" for c in parts[0]):
        return None
    if len(parts) == 2:
        if len(parts[1]) > 2 or any(c not in "0123456789" for c in parts[1]):
            return None
    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    kind, record_id, order_id, amount_text, timestamp_text = fields
    kind = kind.upper()
    if kind not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if kind == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (kind == "ORDER" and amount < 0):
        return None
    if (
        len(timestamp_text) != 16
        or timestamp_text[4] != "-"
        or timestamp_text[7] != "-"
        or timestamp_text[10] != " "
        or timestamp_text[13] != ":"
    ):
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        return None
    return {
        "type": kind,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if record.get("type") == "ORDER":
            orders.append(record)
        elif (
            record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        ):
            payments.append(record)

    results = []
    for order in orders:
        start = order.get("timestamp")
        end = start + timedelta(hours=72)
        chosen = None
        for payment in payments:
            if payment.get("order_id") != order.get("order_id"):
                continue
            timestamp = payment.get("timestamp")
            if start <= timestamp <= end:
                if chosen is None or timestamp < chosen.get("timestamp"):
                    chosen = payment
        if chosen is None:
            results.append({
                "order_id": order.get("order_id"),
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order.get("order_id"),
                "status": "matched",
                "amount": chosen.get("amount"),
            })
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") < 0
        ):
            total += abs(record.get("amount"))
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        status = str(match.get("status", "")).lower()
        if status == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        elif status == "unmatched":
            unmatched_ids.append(match.get("order_id"))

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": sorted(unmatched_ids),
    }

