"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount, timestamp = map(str.strip, fields)
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    if parse_amount(amount) is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parse_amount(amount),
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        valid_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72)
        ]

        if valid_payments:
            chosen_payment = min(valid_payments, key=lambda p: p['timestamp'])
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': chosen_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    if s[0] in "+-":
        sign = -1 if s[0] == "-" else 1
        s = s[1:]
    else:
        sign = 1

    if s == "" or s.count(".") > 1:
        return None

    if "." in s:
        whole, fraction = s.split(".")
    else:
        whole, fraction = s, ""

    if whole == "" or not whole.isdigit():
        return None
    if not fraction.isdigit() or len(fraction) > 2:
        return None

    if len(fraction) == 0:
        fraction_cents = 0
    elif len(fraction) == 1:
        fraction_cents = int(fraction) * 10
    else:
        fraction_cents = int(fraction)

    return sign * (int(whole) * 100 + fraction_cents)


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()

    if record_type not in ("ORDER", "PAYMENT"):
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_id == "" or order_id == "":
        return None

    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None

    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        latest_time = order_time + timedelta(hours=72)

        chosen_payment = None

        for payment in records:
            if (
                not isinstance(payment, dict)
                or payment.get("type") != "PAYMENT"
                or payment.get("order_id") != order_id
                or not isinstance(payment.get("amount"), int)
                or payment["amount"] < 0
            ):
                continue

            payment_time = payment.get("timestamp")
            if payment_time < order_time or payment_time > latest_time:
                continue

            if (
                chosen_payment is None
                or payment_time < chosen_payment.get("timestamp")
            ):
                chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    matched_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status", "")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            matched_total += result.get("amount", 0)
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": matched_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

