      "id": "P5-L1",
      "quote": "Implement `match_payments(records)`."
    },
    {
      "id": "P5-L2",
      "quote": "Produce one result for every `ORDER`, following order-record source order."
    },
    {
      "id": "P5-L3",
      "quote": "Associate non-negative payments by `order_id`."
    },
    {
      "id": "P5-L4",
      "quote": "A payment qualifies only when its timestamp is at or after the order timestamp and no later than exactly 72 hours afterward;"
    },
    {
      "id": "P5-L5",
      "quote": "both endpoints are included."
    },
    {
      "id": "P5-L6",
      "quote": "If several payments qualify, choose the earliest timestamp and retain source order for an exact tie."
