"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str) or s == "":
        return None

    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if s == "" or s.count(".") > 1:
        return None

    if "." in s:
        whole, fraction = s.split(".")
        if fraction == "" or len(fraction) > 2:
            return None
    else:
        whole, fraction = s, ""

    if whole == "" or not whole.isdigit():
        return None
    if fraction and not fraction.isdigit():
        return None

    cents = int(whole) * 100
    if len(fraction) == 1:
        cents += int(fraction) * 10
    elif len(fraction) == 2:
        cents += int(fraction)

    return sign * cents


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(fields[3])
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(fields[4], "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []

    for order in records:
        if order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_time = order.get("timestamp")
        latest = order_time + timedelta(hours=72)
        chosen = None
        chosen_index = None

        for index, payment in enumerate(records):
            if payment.get("type") != "PAYMENT":
                continue
            if payment.get("order_id") != order_id:
                continue

            amount = payment.get("amount")
            payment_time = payment.get("timestamp")
            if amount is None or amount < 0:
                continue
            if payment_time < order_time or payment_time > latest:
                continue

            if (chosen is None or payment_time < chosen.get("timestamp")
                    or (payment_time == chosen.get("timestamp")
                        and index < chosen_index)):
                chosen = payment
                chosen_index = index

        if chosen is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen.get("amount"),
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record.get("type") == "PAYMENT" and record.get("amount") < 0:
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        else:
            unmatched_ids.append(match.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

