"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        if amount.as_tuple().exponent < -2 or amount.as_tuple().exponent > 0:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount, timestamp = map(str.strip, fields)
    record_type = record_type.upper()
    if not record_id or not order_id:
        return None
    if record_type == 'ORDER' and record_id != order_id:
        return None
    parsed_amount = parse_amount(amount)
    if parsed_amount is None or (record_type == 'ORDER' and parsed_amount < 0):
        return None
    try:
        parsed_timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'timestamp': parsed_timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] <= order_timestamp + timedelta(hours=72)
        ]

        if qualifying_payments:
            chosen_payment = min(qualifying_payments, key=lambda p: p['timestamp'])
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': chosen_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'].lower() == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'].lower() == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'].lower() == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None

    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None

    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    try:
        if not isinstance(line, str):
            return None

        fields = line.split("|")
        if len(fields) != 5:
            return None

        type_text, record_id, order_id, amount_text, timestamp_text = fields
        record_type = type_text.upper()

        if record_type not in ("ORDER", "PAYMENT"):
            return None

        record_id = record_id.strip()
        order_id = order_id.strip()

        if not record_id or not order_id:
            return None

        if record_type == "ORDER" and record_id != order_id:
            return None

        amount = parse_amount(amount_text)
        if amount is None:
            return None

        if record_type == "ORDER" and amount < 0:
            return None

        if (
            len(timestamp_text) != 16
            or re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text)
            is None
        ):
            return None

        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")

        return {
            "type": record_type,
            "record_id": record_id,
            "order_id": order_id,
            "amount": amount,
            "timestamp": timestamp,
        }
    except (ValueError, TypeError, OverflowError):
        return None


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []

    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)

    return records


def match_payments(records):
    payments_by_order = {}

    for payment in records:
        if not isinstance(payment, dict):
            continue
        if payment.get("type") != "PAYMENT":
            continue

        amount = payment.get("amount")
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            continue

        order_id = payment.get("order_id")
        timestamp = payment.get("timestamp")
        if order_id is None or not isinstance(timestamp, datetime):
            continue

        payments_by_order.setdefault(order_id, []).append(payment)

    results = []

    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue

        order_id = order.get("order_id")
        order_timestamp = order.get("timestamp")
        chosen_payment = None

        if isinstance(order_timestamp, datetime):
            latest_timestamp = order_timestamp + timedelta(hours=72)

            for payment in payments_by_order.get(order_id, []):
                payment_timestamp = payment["timestamp"]

                if order_timestamp <= payment_timestamp <= latest_timestamp:
                    if (
                        chosen_payment is None
                        or payment_timestamp < chosen_payment["timestamp"]
                    ):
                        chosen_payment = payment

        if chosen_payment is None:
            results.append({
                "order_id": order_id,
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order_id,
                "status": "matched",
                "amount": chosen_payment["amount"],
            })

    return results


def compute_refunds(records):
    total = 0

    for record in records:
        if not isinstance(record, dict):
            continue

        if record.get("type") != "PAYMENT":
            continue

        amount = record.get("amount")
        if isinstance(amount, int) and not isinstance(amount, bool) and amount < 0:
            total += abs(amount)

    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []

    for result in matches:
        status = result.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            amount = result.get("amount", 0)
            if isinstance(amount, int) and not isinstance(amount, bool):
                net_total += amount
        elif isinstance(status, str) and status.lower() == "unmatched":
            unmatched_ids.append(result.get("order_id"))

    unmatched_ids.sort()

    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

