"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    if not isinstance(s, str):
        return None
    if not s:
        return None

    start = 1 if s[0] in "+-" else 0
    body = s[start:]
    if not body:
        return None

    parts = body.split(".")
    if len(parts) > 2:
        return None
    if not parts[0].isdigit():
        return None
    if len(parts) == 2 and (not parts[1].isdigit() or len(parts[1]) > 2):
        return None

    try:
        value = Decimal(s) * 100
        return int(value)
    except (InvalidOperation, ValueError, OverflowError):
        return None


def parse_record(line):
    if not isinstance(line, str):
        return None

    fields = line.split("|")
    if len(fields) != 5:
        return None

    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()

    if record_type not in ("ORDER", "PAYMENT"):
        return None
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None

    amount = parse_amount(amount_text)
    if amount is None:
        return None
    if record_type == "ORDER" and amount < 0:
        return None

    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None

    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str):
        return []

    records = []
    record_ids = set()

    for line in text.splitlines():
        record = parse_record(line)
        if record is None:
            continue

        record_id = record["record_id"]
        if record_id in record_ids:
            continue

        record_ids.add(record_id)
        records.append(record)

    return records


def match_payments(records):
    payments = []
    for source_index, record in enumerate(records):
        if record["type"] == "PAYMENT" and record["amount"] >= 0:
            payments.append((source_index, record))

    results = []
    for order in records:
        if order["type"] != "ORDER":
            continue

        latest = order["timestamp"] + timedelta(hours=72)
        chosen = None

        for source_index, payment in payments:
            if payment["order_id"] != order["order_id"]:
                continue
            if payment["timestamp"] < order["timestamp"]:
                continue
            if payment["timestamp"] > latest:
                continue
            if chosen is None or payment["timestamp"] < chosen["timestamp"]:
                chosen = payment

        if chosen is None:
            results.append({
                "order_id": order["order_id"],
                "status": "unmatched",
                "amount": 0,
            })
        else:
            results.append({
                "order_id": order["order_id"],
                "status": "matched",
                "amount": chosen["amount"],
            })

    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if record["type"] == "PAYMENT" and record["amount"] < 0:
            total += -record["amount"]
    return total


def build_summary(matches, refund_total):
    matched_count = 0
    net_total = -refund_total
    unmatched_ids = []

    for match in matches:
        if match["status"].lower() == "matched":
            matched_count += 1
            net_total += match["amount"]
        else:
            unmatched_ids.append(match["order_id"])

    unmatched_ids.sort()

    return {
        "total_orders": len(matches),
        "matched_count": matched_count,
        "net_total": net_total,
        "unmatched_ids": unmatched_ids,
    }

