"""Blank starter for the simple reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    import re
    if not isinstance(s, str):
        return None
    if re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", s) is None:
        return None
    try:
        return int(Decimal(s) * 100)
    except (InvalidOperation, ValueError, TypeError):
        return None


def parse_record(line):
    import re
    if not isinstance(line, str):
        return None
    fields = line.split("|")
    if len(fields) != 5:
        return None
    record_type, record_id, order_id, amount_text, timestamp_text = fields
    record_type = record_type.upper()
    if record_type not in ("ORDER", "PAYMENT"):
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id:
        return None
    if record_type == "ORDER" and record_id != order_id:
        return None
    amount = parse_amount(amount_text)
    if amount is None or (record_type == "ORDER" and amount < 0):
        return None
    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}", timestamp_text) is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp_text, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    return {
        "type": record_type,
        "record_id": record_id,
        "order_id": order_id,
        "amount": amount,
        "timestamp": timestamp,
    }


def load_records(text):
    if not isinstance(text, str) or text == "":
        return []
    records = []
    for line in text.splitlines():
        record = parse_record(line)
        if record is not None:
            records.append(record)
    return records


def match_payments(records):
    results = []
    payments = []
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record.get("amount") >= 0
        ):
            payments.append(record)
    for order in records:
        if not isinstance(order, dict) or order.get("type") != "ORDER":
            continue
        chosen = None
        for payment in payments:
            if payment.get("order_id") != order.get("order_id"):
                continue
            order_time = order.get("timestamp")
            payment_time = payment.get("timestamp")
            if not isinstance(order_time, datetime) or not isinstance(payment_time, datetime):
                continue
            if order_time <= payment_time <= order_time + timedelta(hours=72):
                if chosen is None or payment_time < chosen.get("timestamp"):
                    chosen = payment
        if chosen is None:
            results.append({"order_id": order.get("order_id"), "status": "unmatched", "amount": 0})
        else:
            results.append({"order_id": order.get("order_id"), "status": "matched", "amount": chosen.get("amount")})
    return results


def compute_refunds(records):
    total = 0
    for record in records:
        if (
            isinstance(record, dict)
            and record.get("type") == "PAYMENT"
            and isinstance(record.get("amount"), int)
            and not isinstance(record.get("amount"), bool)
            and record["amount"] < 0
        ):
            total += abs(record["amount"])
    return total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = 0
    net_total = 0
    unmatched_ids = []
    for match in matches:
        status = match.get("status")
        if isinstance(status, str) and status.lower() == "matched":
            matched_count += 1
            net_total += match.get("amount", 0)
        else:
            unmatched_ids.append(match.get("order_id"))
    unmatched_ids.sort()
    return {
        "total_orders": total_orders,
        "matched_count": matched_count,
        "net_total": net_total - refund_total,
        "unmatched_ids": unmatched_ids,
    }

